using System.Text;
using System.Text.Json;
using EventContracts;
using Microsoft.EntityFrameworkCore;
using RabbitMQ.Client;
using RabbitMQ.Client.Events;

public sealed class Worker(IServiceScopeFactory scopes,IConfiguration config,ILogger<Worker> log):BackgroundService{
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){while(!stoppingToken.IsCancellationRequested){try{using(var init=scopes.CreateScope()){await init.ServiceProvider.GetRequiredService<AuditDb>().Database.MigrateAsync(stoppingToken);}var factory=new ConnectionFactory{Uri=new Uri(config["RabbitMq:Uri"]??Environment.GetEnvironmentVariable("RABBITMQ_URI")??"amqp://guest:guest@localhost:5672/")};await using var connection=await factory.CreateConnectionAsync(stoppingToken);await using var channel=await connection.CreateChannelAsync(cancellationToken:stoppingToken);await channel.ExchangeDeclareAsync("event.topic",ExchangeType.Topic,durable:true,autoDelete:false,cancellationToken:stoppingToken);await channel.QueueDeclareAsync("audit.events",true,false,false,cancellationToken:stoppingToken);foreach(var key in new[]{"event.participant.registered","event.participant.cancelled","event.participant.checkedin","event.event.created","event.event.updated","event.event.deleted"})await channel.QueueBindAsync("audit.events","event.topic",key,cancellationToken:stoppingToken);await channel.BasicQosAsync(0,1,false,stoppingToken);var consumer=new AsyncEventingBasicConsumer(channel);consumer.ReceivedAsync+=async(_,ea)=>{try{var evt=JsonSerializer.Deserialize<BusinessEvent>(Encoding.UTF8.GetString(ea.Body.Span))??throw new InvalidDataException("Invalid event payload");using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AuditDb>();if(await db.Processed.AnyAsync(x=>x.EventId==evt.EventId,stoppingToken)){await channel.BasicAckAsync(ea.DeliveryTag,false,stoppingToken);return;}var d=evt.EventData;db.Entries.Add(new AuditEntry{MessageId=evt.EventId,EventId=d.EventEntityId,EventType=evt.EventType,ParticipantId=d.ParticipantId,ParticipantName=d.ParticipantName,Email=d.Email,RegistrationId=d.RegistrationId,RegistrationCode=d.RegistrationCode,Description=$"{evt.EventType} for {d.ParticipantName} at {d.EventName}",CreatedAt=evt.OccurredAt,CorrelationId=evt.CorrelationId,Payload=JsonSerializer.Serialize(d)});db.Processed.Add(new AuditProcessed{EventId=evt.EventId,ProcessedAt=DateTimeOffset.UtcNow});await db.SaveChangesAsync(stoppingToken);await channel.BasicAckAsync(ea.DeliveryTag,false,stoppingToken);log.LogInformation("Audited {EventType} {EventId} correlation {CorrelationId}",evt.EventType,evt.EventId,evt.CorrelationId);}catch(OperationCanceledException)when(stoppingToken.IsCancellationRequested){throw;}catch(Exception ex){log.LogError(ex,"Audit processing failed; message will be retried");await channel.BasicNackAsync(ea.DeliveryTag,false,true,stoppingToken);}};await channel.BasicConsumeAsync("audit.events",false,consumer,stoppingToken);await Task.Delay(Timeout.Infinite,stoppingToken);}catch(OperationCanceledException)when(stoppingToken.IsCancellationRequested){break;}catch(Exception ex){log.LogError(ex,"Audit RabbitMQ connection lost; reconnecting");await Task.Delay(TimeSpan.FromSeconds(3),stoppingToken);}}}
}
